package com.abluepoint.summer.sample.mcpauthorization;

import com.abluepoint.summer.common.error.SummerException;
import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;
@Service public final class McpAuthorizationService{
 private final Map<String,Permit> permits=new LinkedHashMap<>(); private final HumanApprovalPort approvals;
 public McpAuthorizationService(HumanApprovalPort approvals){this.approvals=approvals;}
 synchronized ExecutionDecisionView decide(ExecutionDecisionRequest r,Authentication a){JwtAuthenticationToken j=requireService(a);if(r==null||!"ent-acme".equals(r.enterpriseId()))throw new AccessDeniedException("Enterprise context denied");assertIdentity(r,j);if(blank(r.connectionServiceId())||blank(r.executionContextId())||blank(r.toolId())||blank(r.toolName())||blank(r.schemaDigest())||blank(r.argumentsDigest())||blank(r.audience()))throw SummerException.withMessage(McpAuthorizationErrorCode.INVALID, "Execution decision fields are required");if(!r.audience().equals("urn:aict:"+r.connectionServiceId()))throw new AccessDeniedException("Permit audience mismatch");String id="inv-"+UUID.randomUUID().toString().substring(0,8);HumanApprovalBinding binding=new HumanApprovalBinding(r.enterpriseId(),r.connectionServiceId(),r.connectionBindingId(),r.externalConnectionId(),r.executionContextId(),j.getToken().getClaimAsString("initiator_principal_id"),r.actorPrincipalId(),r.actorInstanceId(),r.effectiveSubjectPrincipalId(),r.toolId(),r.toolName(),r.schemaDigest(),r.argumentsDigest(),r.audience());if("HIGH".equalsIgnoreCase(r.risk())||"CRITICAL".equalsIgnoreCase(r.risk())){if(blank(r.approvalId())){String approvalId=approvals.createPending(binding);return new ExecutionDecisionView(id,"APPROVAL_REQUIRED",false,"APPROVAL_REQUIRED",approvalId,null);}if(!approvals.consumeApproved(r.approvalId(),binding))throw SummerException.withMessage(McpAuthorizationErrorCode.CONFLICT, "Human approval is missing, expired, consumed, or not bound to this invocation");}Instant now=Instant.now();String pid="permit-"+UUID.randomUUID().toString().substring(0,8);Permit p=new Permit(pid,id,r.enterpriseId(),r.connectionServiceId(),r.connectionBindingId(),r.externalConnectionId(),r.connectionRevision()==null?1:r.connectionRevision(),r.executionContextId(),r.actorPrincipalId(),r.actorInstanceId(),r.effectiveSubjectPrincipalId(),r.toolId(),r.toolName(),r.schemaDigest(),r.argumentsDigest(),r.audience(),"ISSUED",now,now.plusSeconds(300),null,null);permits.put(pid,p);return new ExecutionDecisionView(id,"ALLOW",true,"AUTHORIZED",null,view(p));}
 synchronized PermitClaimView claim(String id,PermitClaimRequest req,Authentication a){JwtAuthenticationToken j=requireService(a);Permit p=permit(id);if(!p.connectionServiceId.equals(j.getToken().getClaimAsString("connection_service_id")))throw new AccessDeniedException("Permit audience service mismatch");if(p.expiresAt.isBefore(Instant.now())||"REVOKED".equals(p.status))throw SummerException.withMessage(McpAuthorizationErrorCode.CONFLICT, "Permit is not claimable");if(req==null||blank(req.executionAttemptId()))throw SummerException.withMessage(McpAuthorizationErrorCode.INVALID, "executionAttemptId is required");if(p.attempt!=null&&!p.attempt.equals(req.executionAttemptId()))throw SummerException.withMessage(McpAuthorizationErrorCode.CONFLICT, "Permit already claimed by another attempt");if(p.attempt==null){p.attempt=req.executionAttemptId();p.status="CLAIMED";p.claimedAt=Instant.now();}return new PermitClaimView(p.id,p.invocationId,p.attempt,p.status,p.claimedAt);}
 synchronized ExecutionPermitView revoke(String enterpriseId,String id,Authentication a){requireAdmin(enterpriseId,a);Permit p=permit(id);if(!enterpriseId.equals(p.enterpriseId))throw new AccessDeniedException("Enterprise context denied");p.status="REVOKED";return view(p);}
 public synchronized ExecutionPermitView getPermit(String id){return view(permitInternal(id));}
 public synchronized PublicPermitSnapshot snapshot(String id){Permit p=permitInternal(id);return new PublicPermitSnapshot(p.id,p.invocationId,p.enterpriseId,p.connectionServiceId,p.connectionBindingId,p.externalConnectionId,p.connectionRevision,p.executionContextId,p.actorPrincipalId,p.actorInstanceId,p.effectiveSubjectPrincipalId,p.toolId,p.toolName,p.schemaDigest,p.argumentsDigest,p.audience,p.status);}
 public synchronized PermitClaimView claimForExecution(String id, String attempt, Authentication auth){return claim(id,new PermitClaimRequest(attempt),auth);}
 public synchronized boolean matches(String id,String schema,String args,String service,String context){Permit p=permitInternal(id);return p.connectionServiceId.equals(service)&&p.executionContextId.equals(context)&&p.schemaDigest.equals(schema)&&p.argumentsDigest.equals(args)&&p.status.equals("CLAIMED");}
 private JwtAuthenticationToken requireService(Authentication a){if(!(a instanceof JwtAuthenticationToken j)||!Boolean.TRUE.equals(j.getToken().getClaimAsBoolean("service_trust_verified"))||j.getAuthorities().stream().noneMatch(x->"SCOPE_internal.mcp.execution.decide".equals(x.getAuthority())))throw new AccessDeniedException("Connection service trust denied");return j;}
 private void assertIdentity(ExecutionDecisionRequest r,JwtAuthenticationToken j){if(!Objects.equals(r.executionContextId(),j.getToken().getClaimAsString("execution_context_id"))||!Objects.equals(r.actorPrincipalId(),j.getToken().getClaimAsString("actor_principal_id"))||!Objects.equals(r.effectiveSubjectPrincipalId(),j.getToken().getClaimAsString("effective_subject_principal_id"))||!Objects.equals(r.actorInstanceId(),j.getToken().getClaimAsString("actor_instance_id")))throw new AccessDeniedException("Caller identity mismatch");}
 private void requireAdmin(String e,Authentication a){if(!(a instanceof JwtAuthenticationToken j)||!"ent-acme".equals(e)||!active(j,e)||!cap(j,e,"enterprise.mcp.execution.write")||j.getAuthorities().stream().noneMatch(x->"SCOPE_enterprise.mcp.execution.write".equals(x.getAuthority())))throw new AccessDeniedException("MCP execution capability denied");}
 private boolean active(JwtAuthenticationToken j,String e){Object v=j.getToken().getClaims().get("enterprise_memberships");return v instanceof Collection<?> c&&c.stream().filter(Map.class::isInstance).map(x->(Map<?,?>)x).anyMatch(m->e.equals(String.valueOf(m.getOrDefault("enterpriseId",m.get("enterprise_id"))))&&"ACTIVE".equalsIgnoreCase(String.valueOf(m.getOrDefault("status",m.get("membership_status")))));}
 private boolean cap(JwtAuthenticationToken j,String e,String c){Object v=j.getToken().getClaims().get("enterprise_capabilities");if(!(v instanceof Map<?,?>m))return false;Object g=m.get(e);return g instanceof Collection<?>x&&x.stream().map(String::valueOf).anyMatch(c::equals);}
 private Permit permit(String id){return permitInternal(id);} private Permit permitInternal(String id){Permit p=permits.get(id);if(p==null)throw SummerException.withMessage(McpAuthorizationErrorCode.CONFLICT, "Permit not found");return p;}private static boolean blank(String s){return s==null||s.isBlank();}private ExecutionPermitView view(Permit p){return new ExecutionPermitView(p.id,p.invocationId,p.enterpriseId,p.connectionServiceId,p.connectionBindingId,p.externalConnectionId,p.connectionRevision,p.executionContextId,p.actorPrincipalId,p.actorInstanceId,p.effectiveSubjectPrincipalId,p.toolId,p.schemaDigest,p.argumentsDigest,p.audience,p.status,p.issuedAt,p.expiresAt);}
 private static final class Permit{final String id,invocationId,enterpriseId,connectionServiceId,connectionBindingId,externalConnectionId,executionContextId,actorPrincipalId,actorInstanceId,effectiveSubjectPrincipalId,toolId,toolName,schemaDigest,argumentsDigest,audience;final long connectionRevision;final Instant issuedAt,expiresAt;String status,attempt;Instant claimedAt;Permit(String i,String n,String e,String s,String b,String x,long r,String c,String a,String ai,String sub,String t,String tn,String sd,String ad,String au,String st,Instant is,Instant ex,String at,Instant ca){id=i;invocationId=n;enterpriseId=e;connectionServiceId=s;connectionBindingId=b;externalConnectionId=x;connectionRevision=r;executionContextId=c;actorPrincipalId=a;actorInstanceId=ai;effectiveSubjectPrincipalId=sub;toolId=t;toolName=tn;schemaDigest=sd;argumentsDigest=ad;audience=au;status=st;issuedAt=is;expiresAt=ex;attempt=at;claimedAt=ca;}}
}
